## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/highMyopiaLogic.ts`

```typescript
/**
 * High Myopia / Pathologic Myopia Clinical Logic Engine
 * Based on: IMI (International Myopia Institute) 2023 White Papers,
 *            AAO 2024 Preferred Practice Pattern, WSPOS 2023 Consensus
 * Key decisions: Myopia control in children, pathologic myopia complications,
 *                myopic CNV treatment, surgical correction candidacy
 */

export type MyopiaLevel =
  | 'low' // -0.5 to -3.0D
  | 'moderate' // -3.25 to -6.0D
  | 'high' // -6.25 to -10.0D
  | 'extreme'; // > -10.0D

export type AxialLength = 'normal' | 'long' | 'very_long'; // <26mm, 26–28mm, >28mm

export type MyopiaControlHistory =
  | 'none'
  | 'on_atropine_low'
  | 'on_atropine_high'
  | 'on_orthokeratology'
  | 'on_mf_soft_lens'
  | 'on_combination';

export type PathologicComplication =
  | 'none'
  | 'myopic_cnv'
  | 'myopic_traction_maculopathy'
  | 'retinal_detachment'
  | 'posterior_staphyloma'
  | 'lacquer_cracks'
  | 'dome_shaped_macula';

export interface HighMyopiaInput {
  age: number;
  sphericalEquivalent: number; // negative diopters, e.g., -8.5
  axialLength: AxialLength;
  myopiaLevel: MyopiaLevel;
  isProgressing: boolean; // >0.5D/year in children
  myopiaControlHistory: MyopiaControlHistory;
  pathologicComplication: PathologicComplication;
  hasFamilyHistoryMyopia: boolean;
  timeOutdoorsHoursPerDay: number; // <2 hours is a risk factor
  screenTimeHoursPerDay: number;
  bestCorrectedVA: string; // e.g., "20/40"
  hasMyopicCNV: boolean;
  cnvAntiVEGFHistory: 'none' | 'on_treatment' | 'completed';
  isSurgicalCandidateForRefractiveSurgery: boolean;
  cornealThickness?: number; // microns, relevant for LASIK
  hasKeratoconus: boolean;
}

export interface HighMyopiaRecommendation {
  primaryRecommendation: string;
  myopiaControlStrategy: string;
  pathologicManagement: string;
  surgicalConsideration: string;
  monitoringPlan: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessHighMyopia(input: HighMyopiaInput): HighMyopiaRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // Urgent flags
  if (input.pathologicComplication === 'retinal_detachment') {
    urgentFlags.push('RETINAL DETACHMENT: urgent surgical referral required — same-day evaluation');
  }
  if (input.hasMyopicCNV && input.cnvAntiVEGFHistory === 'none') {
    urgentFlags.push('MYOPIC CNV: urgent anti-VEGF injection required — ranibizumab or bevacizumab. Delay worsens prognosis.');
  }
  if (input.pathologicComplication === 'myopic_traction_maculopathy') {
    urgentFlags.push('Myopic traction maculopathy: urgent vitreoretinal surgery referral — risk of foveal detachment');
  }
  if (input.sphericalEquivalent <= -10 && input.axialLength === 'very_long') {
    urgentFlags.push('Extreme myopia (>-10D) with very long axial length: high risk for pathologic complications — annual dilated exam with OCT macula mandatory');
  }

  // Myopia control strategy (primarily for children/adolescents)
  let myopiaControlStrategy = '';
  if (input.age <= 18 && input.isProgressing) {
    if (input.myopiaControlHistory === 'none') {
      myopiaControlStrategy =
        'Progressing myopia in child/adolescent: myopia control intervention recommended (IMI 2023 Level A). ' +
        'Options by efficacy: ' +
        '1) Low-dose atropine 0.01–0.05% nightly — ATOM2 trial: 50–60% reduction in progression. Minimal side effects. PREFERRED first-line. ' +
        '2) Orthokeratology (OK lenses) — 30–50% reduction in axial elongation. Good for moderate myopia. ' +
        '3) Multifocal soft contact lenses (MiSight 1-day) — FDA-approved; 59% reduction in progression (Cooper Vision BLINK study). ' +
        '4) Combination atropine + OK lenses — highest efficacy for rapidly progressing myopia. ' +
        'Outdoor time: ≥2 hours/day reduces myopia onset by 50% (meta-analysis). Counsel family.';
      nextSteps.push(
        'Cycloplegic refraction to confirm myopia level',
        'Axial length measurement (IOLMaster or Lenstar) — baseline and every 6 months',
        'Discuss myopia control options with family',
        'Prescribe low-dose atropine 0.01–0.05% nightly as first-line',
        'Encourage ≥2 hours outdoor time daily'
      );
    } else if (input.myopiaControlHistory === 'on_atropine_low') {
      myopiaControlStrategy =
        'On low-dose atropine with continued progression: increase atropine concentration (0.025% or 0.05%) or add orthokeratology. ' +
        'Combination therapy (atropine + OK lenses) provides additive benefit for rapidly progressing cases.';
      nextSteps.push('Increase atropine to 0.025% or 0.05%', 'Consider adding orthokeratology', 'Recheck axial length in 6 months');
    } else {
      myopiaControlStrategy =
        `On ${input.myopiaControlHistory.replace(/_/g, ' ')}: assess axial length progression rate. ` +
        'If >0.3mm/year axial elongation, consider escalating or combining therapies. ' +
        'Reassess every 6 months.';
    }
  } else if (input.age > 18) {
    myopiaControlStrategy =
      'Adult myopia: stabilization expected after age 18–25. Myopia control interventions not indicated for adults. ' +
      'Focus on correction (spectacles, contact lenses, refractive surgery) and monitoring for pathologic complications.';
  } else {
    myopiaControlStrategy =
      'Stable myopia: continue current correction. Encourage outdoor time. Annual monitoring.';
  }

  // Pathologic myopia management
  let pathologicManagement = '';
  if (input.pathologicComplication === 'myopic_cnv' || input.hasMyopicCNV) {
    pathologicManagement =
      'Myopic CNV: anti-VEGF is first-line treatment (RADIANCE trial — ranibizumab superior to PDT). ' +
      'Ranibizumab 0.5mg IVT — RADIANCE trial: 1–3 injections typically sufficient (myopic CNV often self-limiting). ' +
      'Bevacizumab 1.25mg IVT — off-label, similar efficacy, lower cost. ' +
      'Aflibercept and faricimab — less data for myopic CNV specifically. ' +
      'Prognosis: generally better than nAMD — smaller lesions, younger patients, fewer injections needed.';
    nextSteps.push('FA/OCTA to confirm CNV type and activity', 'Anti-VEGF injection (ranibizumab or bevacizumab)', 'OCT at 4–6 weeks post-injection to assess response');
  } else if (input.pathologicComplication === 'myopic_traction_maculopathy') {
    pathologicManagement =
      'Myopic traction maculopathy (MTM): observation for mild cases (no foveal detachment). ' +
      'Vitrectomy + ILM peeling for progressive MTM or foveal detachment. ' +
      'Macular buckle is an alternative for dome-shaped macula with MTM. ' +
      'OCT macula every 3–6 months to monitor for progression.';
    nextSteps.push('OCT macula (assess foveal detachment, schisis, macular hole)', 'Vitreoretinal surgery referral if foveal detachment or progressive schisis');
  } else if (input.pathologicComplication === 'posterior_staphyloma') {
    pathologicManagement =
      'Posterior staphyloma: no direct treatment available. Monitor for secondary complications (MTM, CNV, atrophy). ' +
      'Annual OCT macula + fundus photography. Avoid contact sports and activities with risk of ocular trauma.';
    nextSteps.push('Annual OCT macula', 'Fundus photography for documentation', 'Low vision referral if BCVA <20/200');
  } else if (input.pathologicComplication === 'lacquer_cracks') {
    pathologicManagement =
      'Lacquer cracks: monitor for CNV development (occurs in ~5% of eyes with lacquer cracks). ' +
      'OCT + FA if any new visual symptoms. Annual dilated exam.';
    nextSteps.push('Annual OCT macula', 'Educate patient to report any sudden vision change or metamorphopsia');
  } else {
    pathologicManagement =
      input.myopiaLevel === 'high' || input.myopiaLevel === 'extreme'
        ? 'High/extreme myopia without current pathologic complication: annual dilated fundus exam + OCT macula mandatory. ' +
          'Educate patient on warning symptoms (flashes, floaters, curtain/shadow in vision — retinal detachment). ' +
          'Avoid contact sports and high-impact activities.'
        : 'No pathologic complication identified. Standard monitoring.';
  }

  // Surgical consideration
  let surgicalConsideration = '';
  if (input.isSurgicalCandidateForRefractiveSurgery && !input.hasKeratoconus) {
    if (input.sphericalEquivalent >= -10) {
      surgicalConsideration =
        'Refractive surgery considerations: ' +
        'LASIK: suitable for myopia up to -8D to -10D (corneal thickness dependent). Requires corneal thickness >500μm and residual stromal bed >250μm. ' +
        'PRK/LASEK: preferred over LASIK for thin corneas or high-risk occupations (contact sports). ' +
        'ICL (implantable collamer lens): preferred for high myopia >-8D or thin corneas — STAAR Visian ICL. Excellent safety profile. ' +
        'SMILE (small incision lenticule extraction): up to -10D, no flap created.';
    } else {
      surgicalConsideration =
        'Extreme myopia (>-10D): ICL (implantable collamer lens) is preferred over laser refractive surgery. ' +
        'LASIK/PRK may be combined with ICL for residual correction. ' +
        'Refractive lens exchange (RLE) for patients >40 years with presbyopia.';
    }
  } else if (input.hasKeratoconus) {
    surgicalConsideration =
      'Keratoconus present: LASIK is CONTRAINDICATED. ' +
      'Rigid gas-permeable (RGP) or scleral contact lenses for correction. ' +
      'Corneal collagen cross-linking (CXL) to halt keratoconus progression. ' +
      'ICL may be considered in stable keratoconus with specialist evaluation.';
    urgentFlags.push('Keratoconus: LASIK contraindicated — refer to cornea specialist');
  } else {
    surgicalConsideration = 'Refractive surgery candidacy not assessed or not indicated at this time.';
  }

  // Monitoring plan
  let monitoringPlan = '';
  if (input.myopiaLevel === 'high' || input.myopiaLevel === 'extreme') {
    monitoringPlan =
      'High/extreme myopia: annual dilated fundus exam + OCT macula + fundus photography. ' +
      'Axial length measurement every 6–12 months (children). ' +
      'Immediate evaluation for: flashes, floaters, new scotoma, curtain/shadow in vision (retinal detachment risk).';
  } else if (input.age <= 18 && input.isProgressing) {
    monitoringPlan =
      'Progressing childhood myopia: axial length every 6 months. Cycloplegic refraction annually. ' +
      'Reassess myopia control therapy efficacy every 6–12 months.';
  } else {
    monitoringPlan = 'Annual dilated fundus exam. Refraction as needed for symptom changes.';
  }

  const rationale =
    `Myopia level: ${input.myopiaLevel} (${input.sphericalEquivalent}D). ` +
    `Age: ${input.age}. ` +
    `Axial length: ${input.axialLength}. ` +
    `Progressing: ${input.isProgressing ? 'Yes' : 'No'}. ` +
    `Pathologic complication: ${input.pathologicComplication.replace(/_/g, ' ')}. ` +
    `Myopic CNV: ${input.hasMyopicCNV ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.pathologicComplication !== 'none' || input.hasMyopicCNV
        ? `Pathologic myopia with ${input.hasMyopicCNV ? 'myopic CNV' : input.pathologicComplication.replace(/_/g, ' ')}: urgent management indicated.`
        : input.age <= 18 && input.isProgressing
        ? 'Progressing childhood myopia: myopia control intervention recommended to reduce long-term pathologic risk.'
        : `${input.myopiaLevel.charAt(0).toUpperCase() + input.myopiaLevel.slice(1)} myopia: correction and monitoring. ${input.myopiaLevel === 'high' || input.myopiaLevel === 'extreme' ? 'Annual OCT macula mandatory.' : ''}`,
    myopiaControlStrategy,
    pathologicManagement,
    surgicalConsideration,
    monitoringPlan,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Flitcroft DI, et al. IMI – Defining and Classifying Myopia: A Proposed Set of Standards for Clinical and Epidemiologic Studies. Invest Ophthalmol Vis Sci. 2019;60(3):M20-M30.',
        pmid: '30817826',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30817826/',
      },
      {
        citation: 'Yam JC, et al. Low-Concentration Atropine for Myopia Progression (LAMP) Study. Ophthalmology. 2019;126(1):113-124.',
        pmid: '30514630',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30514630/',
      },
      {
        citation: 'Bullimore MA, et al. The IMI 2023 Myopia Control Report. Invest Ophthalmol Vis Sci. 2023;64(6):3.',
        pmid: '37195759',
        url: 'https://pubmed.ncbi.nlm.nih.gov/37195759/',
      },
      {
        citation: 'Wolf S, et al. RADIANCE: A Randomized Controlled Study of Ranibizumab in Patients with Choroidal Neovascularization Secondary to Pathologic Myopia. Ophthalmology. 2014;121(3):682-692.',
        pmid: '24289920',
        url: 'https://pubmed.ncbi.nlm.nih.gov/24289920/',
      },
      {
        citation: 'Ohno-Matsui K, et al. International Photographic Classification and Grading System for Myopic Maculopathy. Am J Ophthalmol. 2015;159(5):877-883.',
        pmid: '25634530',
        url: 'https://pubmed.ncbi.nlm.nih.gov/25634530/',
      },
      {
        citation: 'AAO Preferred Practice Pattern: Myopia. American Academy of Ophthalmology. 2024.',
        url: 'https://www.aao.org/preferred-practice-pattern/myopia-ppp',
      },
    ],
  };
}

export function getMyopiaLevelColor(level: MyopiaLevel): string {
  switch (level) {
    case 'low': return 'text-green-700 bg-green-50 border-green-200';
    case 'moderate': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'high': return 'text-orange-700 bg-orange-50 border-orange-200';
    case 'extreme': return 'text-red-700 bg-red-50 border-red-200';
  }
}
